const q = $('Question').first().json.question;
const a = $json.answers || {};
let route = a.route?.choice || 'filings';
const ticker = a.ticker?.choice || 'NONE';
const metric = a.metric?.choice || 'other';

const mentionsCovered = Object.entries(COMPANIES).some(([t, co]) => {
  const nm = co.name.toLowerCase().replace(/\(.*\)/, '').trim();
  return new RegExp('\\b' + t + '\\b', 'i').test(q) || q.toLowerCase().includes(nm) || q.toLowerCase().includes(nm.split(' ')[0].length > 3 ? nm.split(' ')[0] : nm) || (t === 'GOOGL' && /google/i.test(q));
});
const outOfScope = (route === 'filings' || route === 'numbers') && ticker === 'NONE' && !mentionsCovered;
if (!q || outOfScope) route = 'direct';
// Fixed rule (not the model's guess): attempts to override the rules, or to get a buy/sell instruction, always get a short decline
const advice = /ignore\s+(all\s+|any\s+|your\s+|the\s+|previous\s+|prior\s+)*(rules|instructions|guidelines)|disregard\s+(your|the|all)\s+(rules|instructions)|tell me to\s+(buy|sell)/i.test(q);
if (advice) route = 'direct';
if ((route === 'filings' || route === 'numbers') && ticker === 'NONE') route = 'web';
if (route === 'numbers' && metric === 'other') route = 'filings';

const co = COMPANIES[ticker];
return [{ json: {
  question: q, route, ticker, metric, outOfScope, advice,
  company: co?.name || null,
  cik10: co ? String(co.cik).padStart(10, '0') : null,
  routeConfidence: a.route?.confidence ?? null,
  routeProbabilities: a.route?.probabilities ?? null,
}}];

function gradeBody(question, context, what) {
  return {
    model: 'typesafe/jev-1.14-20261014',
    state: [`User question: ${question}`, `${what}:\n${context || '(empty)'}`],
    questions: {
      sufficient: {
        type: 'noul',
        instructions: `Does the ${what.toLowerCase()} contain the specific information needed to answer the user question accurately (right company, right period, right figure)?`,
        criteria: {
          true: 'The context directly contains the facts or figures needed to answer the question.',
          false: 'The context is empty, off-topic, about a different company or period, or only partially answers the question.',
        },
      },
    },
  };
}


// Broad filing questions (risks, strategy, business) can only be covered in part by the excerpts, so ask "on topic, right company?" instead of "fully answered?"
function kbBody(question, context) {
  const b = gradeBody(question, context, 'Retrieved SEC filing excerpts');
  b.questions.sufficient.instructions = 'Do the filing excerpts discuss the topic the user asked about, for the right company and period?';
  b.questions.sufficient.criteria = {
    true: 'The excerpts are from the right company and directly discuss what was asked, even if they cover only part of a broad question such as risks or strategy.',
    false: 'The excerpts are empty, from a different company or period, or unrelated to what was asked.',
  };
  return b;
}

const q = $('Question').first().json.question;
const docs = $input.all()
  .map(i => i.json.document || (i.json.pageContent ? i.json : null))
  .filter(Boolean);

const parts = docs.map((doc, i) => {
  const m = doc.metadata || {};
  return `[${i + 1}] ${m.company || ''} (${m.ticker || ''}) Form ${m.form || ''}, period ending ${m.reportDate || '?'}, filed ${m.filingDate || '?'}\n${String(doc.pageContent || '').slice(0, 2500)}`;
});
const context = parts.join('\n\n---\n\n').slice(0, 24000);   // stay well under Jev's ~32KB fast mode
const sources = [...new Set(docs.map(d => d.metadata?.url).filter(Boolean))];

return [{ json: { question: q, mode: 'kb', context, sources,
  gradeBody: kbBody(q, context) } }];

const ctx = $('KB Context').first().json;
const p = $json.answers?.sufficient?.noul ?? 0;
const { gradeBody, ...rest } = ctx;
return [{ json: { ...rest, kbScore: p, good: p >= 0.45 } }];

function gradeBody(question, context, what) {
  return {
    model: 'typesafe/jev-1.14-20261014',
    state: [`User question: ${question}`, `${what}:\n${context || '(empty)'}`],
    questions: {
      sufficient: {
        type: 'noul',
        instructions: `Does the ${what.toLowerCase()} contain the specific information needed to answer the user question accurately (right company, right period, right figure)?`,
        criteria: {
          true: 'The context directly contains the facts or figures needed to answer the question.',
          false: 'The context is empty, off-topic, about a different company or period, or only partially answers the question.',
        },
      },
    },
  };
}

const q = $('Question').first().json.question;
const results = $json.results || [];
const parts = results.map((r, i) =>
  `[W${i + 1}] ${r.title || ''} (${r.url})${r.published_at ? ' — published ' + r.published_at : ''}\n${r.snippet || r.description || ''}`);
const context = parts.join('\n\n---\n\n').slice(0, 20000);
return [{ json: { question: q, mode: 'web', context,
  sources: results.map(r => r.url).filter(Boolean),
  gradeBody: gradeBody(q, context, 'Web search results') } }];

const ctx = $('Web Context').first().json;
const p = $json.answers?.sufficient?.noul ?? 0;
const { gradeBody, ...rest } = ctx;
return [{ json: { ...rest, webScore: p, good: p >= 0.6 } }];

// Neither KB nor web was graded good enough: answer with whatever we have and say so.
const web = $json;
let kb = null;
try { kb = $('KB Verdict').first().json; } catch (e) { kb = null; }
const context = [kb?.context, web.context].filter(Boolean).join('\n\n=====\n\n').slice(0, 24000);
const sources = [...new Set([...(kb?.sources || []), ...(web.sources || [])])];
return [{ json: { question: web.question, mode: 'fallback', context, sources } }];

const d = $('Decide Route').first().json;
const facts = $json.facts || {};
const CANDIDATES = {
  revenue: [['us-gaap','RevenueFromContractWithCustomerExcludingAssessedTax'],['us-gaap','Revenues'],['us-gaap','SalesRevenueNet'],['us-gaap','RevenueFromContractWithCustomerIncludingAssessedTax']],
  net_income: [['us-gaap','NetIncomeLoss']],
  eps_diluted: [['us-gaap','EarningsPerShareDiluted']],
  operating_income: [['us-gaap','OperatingIncomeLoss']],
  gross_profit: [['us-gaap','GrossProfit']],
  rd_expense: [['us-gaap','ResearchAndDevelopmentExpense'],['us-gaap','ResearchAndDevelopmentExpenseExcludingAcquiredInProcessCost']],
  operating_cash_flow: [['us-gaap','NetCashProvidedByUsedInOperatingActivities']],
  cash: [['us-gaap','CashAndCashEquivalentsAtCarryingValue']],
  total_assets: [['us-gaap','Assets']],
  long_term_debt: [['us-gaap','LongTermDebtNoncurrent'],['us-gaap','LongTermDebt']],
};

// Pick the candidate concept with the most recent data (companies switch tags over time)
let best = null;
for (const [tax, name] of (CANDIDATES[d.metric] || [])) {
  const concept = facts[tax]?.[name];
  if (!concept) continue;
  const unit = Object.keys(concept.units || {})[0];
  const rows = (concept.units[unit] || []).filter(r => ['10-K', '10-Q', '10-K/A', '10-Q/A'].includes(r.form));
  if (!rows.length) continue;
  const latest = rows.reduce((m, r) => (r.end > m ? r.end : m), '');
  if (!best || latest > best.latest) best = { name, unit, rows, latest, label: concept.label };
}

if (!best) {
  return [{ json: { ...d, found: false } }];
}

// Dedupe by period, keep the latest-filed value, label duration (quarter / YTD / annual / point in time)
const byPeriod = {};
for (const r of best.rows) {
  const k = `${r.start || ''}|${r.end}`;
  if (!byPeriod[k] || r.filed > byPeriod[k].filed) byPeriod[k] = r;
}
const days = r => r.start ? Math.round((new Date(r.end) - new Date(r.start)) / 86400000) : 0;
const kind = r => { const n = days(r); if (!r.start) return 'as of'; if (n < 100) return 'quarter'; if (n > 350) return 'full year'; return `${Math.round(n / 30)}-month YTD`; };
const fmt = v => Math.abs(v) >= 1e6 ? `${(v / 1e9).toFixed(3)} billion` : String(v);

const rows = Object.values(byPeriod).sort((a, b) => b.end.localeCompare(a.end)).slice(0, 16);
const lines = rows.map(r =>
  `- ${kind(r)} ${r.start ? r.start + ' to ' : ''}${r.end}: ${fmt(r.val)} ${best.unit} (exact: ${r.val}; form ${r.form}, filed ${r.filed}, accession ${r.accn})`);

const context = `${d.company} (${d.ticker}) — ${best.label} [XBRL tag ${best.name}], unit ${best.unit}.\n` +
  `Source: SEC XBRL company facts. Use the period dates, NOT fiscal-year labels.\n` + lines.join('\n');

return [{ json: {
  ...d, found: true, mode: 'numbers', context,
  sources: [`https://data.sec.gov/api/xbrl/companyfacts/CIK${d.cik10}.json`],
}}];

const get = (name) => { try { return $(name).first().json; } catch (e) { return null; } };
const ai = get('Answer Input') || {};
const route = get('Decide Route') || {};
const kb = get('KB Verdict'), web = get('Web Verdict'), fig = get('Extract Figures');
return [{ json: {
  question: ai.question ?? get('Question')?.question,
  answer: String($json.text || '').trim(),
  mode: ai.mode,
  sources: ai.sources || [],
  route: route.route ?? null, ticker: route.ticker ?? null, metric: route.metric ?? null,
  kbScore: kb ? kb.kbScore : null, webScore: web ? (web.webScore ?? web.score ?? null) : null,
  visited: ['Search Filings (Pinecone)','SEC XBRL Facts','Keenable Search','Direct','Fallback'].filter(n => { try { $(n).first(); return true; } catch (e) { return false; } }),
  figures: fig ? (fig.figures ?? fig.facts ?? null) : null
} }];

const hits = ($input.first().json.matches || []);
if (!hits.length) return [{ json: {} }];   // nothing found: KB Context then grades empty context and falls back to web
return hits.map(h => ({ json: { document: { pageContent: h.chunk_text || '', metadata: { ticker: h.ticker, company: h.company, form: h.form, filingDate: h.filingDate, reportDate: h.reportDate, url: h.url, source: h.source } } } }));
